5	  <meta name="viewport" content="width=device-width, initial-scale=1.0">
6	  <meta name="color-scheme" content="light dark">
7	  <title>Animated Circle - Interactive Demo</title>
8	  <meta name="description" content="A responsive, accessible circle that changes color when clicked">
9	  <meta name="theme-color" content="#ffffff" media="(prefers-color-scheme: light)">
10	  <meta name="theme-color" content="#111111" media="(prefers-color-scheme: dark)">
11	  <link rel="icon" href="data:,">
12	  <style>
13	    *,
14	    *::before,
15	    *::after {
16	      box-sizing: border-box;
17	      margin: 0;
18	      padding: 0;
19	    }
20	    :root {
21	      color-scheme: light dark;
22	      --bg: #fff;
23	      --text: #374151;
24	      --fg: #2563eb;
25	      --shadow: rgba(0, 0, 0, 0.1);
26	      --kbd-bg: rgba(0, 0, 0, 0.1);
27	      --drop: drop-shadow(0 4px 12px var(--shadow));
28	    }
29	    [data-color="red"] { --fg: #dc2626; }
30	    /* Dark enough to keep 3:1 against --bg at the resting 0.85 opacity */
31	    [data-color="green"] { --fg: #15803d; }
32	    [data-color="amber"] { --fg: #b45309; }
33	    [data-color="violet"] { --fg: #7c3aed; }
34	    [data-color="cyan"] { --fg: #0e7490; }
35	    @media (prefers-color-scheme: dark) {
36	      :root {
37	        --bg: #111;
38	        --text: #d1d5db;
39	        --fg: #93c5fd;
40	        --shadow: rgba(0, 0, 0, 0.6);
41	        --kbd-bg: rgba(255, 255, 255, 0.15);
42	      }
43	      [data-color="red"] { --fg: #fca5a5; }
44	      [data-color="green"] { --fg: #86efac; }
45	      [data-color="amber"] { --fg: #fcd34d; }
46	      [data-color="violet"] { --fg: #c4b5fd; }
47	      [data-color="cyan"] { --fg: #67e8f9; }
48	    }
49	    @media (prefers-contrast: more) {
50	      :root {
51	        --shadow: rgba(0, 0, 0, 0.9);
52	        --drop: drop-shadow(0 2px 8px var(--shadow));
53	      }
54	      .circle svg {
55	        opacity: 1;
56	      }
57	    }
58	    @media (forced-colors: active) {
59	      svg circle {
60	        stroke: CanvasText;
61	        stroke-width: 2;
62	      }
63	    }
64	    body {
65	      min-height: 100vh;
66	      min-height: 100dvh;
67	      display: grid;
68	      place-items: center;
69	      padding: 1rem;
70	      background: var(--bg);
71	      color: var(--text);
72	      font-family: system-ui, -apple-system, sans-serif;
73	    }
74	    main {
75	      width: 100%;
76	      display: flex;
77	      flex-direction: column;
78	      align-items: center;
79	      text-align: center;
80	    }
81	    .circle {
82	      display: block;
83	      width: min(360px, 100%, 60vh);
84	      aspect-ratio: 1;
85	      border: 0;
86	      border-radius: 50%;
87	      background: none;
88	      color: var(--fg);
89	      cursor: pointer;
90	      touch-action: manipulation;
91	      -webkit-tap-highlight-color: transparent;
92	      /* Shift+click and double-click would otherwise select the text below */
93	      -webkit-user-select: none;
94	      user-select: none;
95	      transition: color 0.4s ease;
96	      min-height: 48px;
97	      min-width: 48px;
98	    }
99	    .no-transition,
100	    .no-transition svg {
101	      transition: none !important;
102	    }
103	    .circle:focus-visible {
104	      outline: 3px solid currentColor;
105	      /* Must clear the scaled-up circle (up to 9px) or the ring merges with it */
106	      outline-offset: 12px;
107	    }
108	    svg {
109	      display: block;
110	      width: 100%;
111	      height: 100%;
112	      overflow: visible;
113	      opacity: 0.85;
114	      filter: var(--drop);
115	      transition: opacity 0.3s ease;
116	    }
117	    .circle:active svg,
118	    .circle:focus-visible svg {
119	      opacity: 1;
120	    }
121	    @keyframes pulse {
122	      0% {
123	        filter: var(--drop) drop-shadow(0 0 16px currentColor);
124	      }
125	      100% {
126	        filter: var(--drop) drop-shadow(0 0 0 transparent);
127	      }
128	    }
129	    @media (hover: hover) {
130	      .circle:hover svg {
131	        opacity: 1;
132	      }
133	    }
134	    @media (prefers-reduced-motion: no-preference) {
135	      svg {
136	        transition:
137	          transform 0.3s cubic-bezier(0.34, 1.56, 0.64, 1),
138	          opacity 0.3s ease;
139	      }
140	      .circle:focus-visible svg {
141	        transform: scale(1.05);
142	      }
143	      .circle:active svg {
144	        transform: scale(0.97);
145	      }
146	      .circle.color-changed svg {
147	        animation: pulse 0.5s ease-out;
148	      }
149	    }
150	    @media (hover: hover) and (prefers-reduced-motion: no-preference) {
151	      .circle:hover:not(:active) svg {
152	        transform: scale(1.05);
153	      }
154	    }
155	    .visually-hidden {
156	      position: absolute;
157	      width: 1px;
158	      height: 1px;
159	      overflow: hidden;
160	      clip-path: inset(50%);
161	      white-space: nowrap;
162	    }
163	    .status {
164	      margin-top: 2rem;
165	      font-weight: 600;
166	    }
167	    .hint {
168	      margin-top: 0.25rem;
169	      font-size: 0.875rem;
170	      line-height: 1.75;
171	      text-wrap: balance;
172	    }
173	    .help-button {
174	      margin-left: 0.5rem;
175	      display: inline-block;
176	      width: 1.5rem;
177	      height: 1.5rem;
178	      border-radius: 50%;
179	      background: var(--kbd-bg);
180	      border: 1px solid var(--text);
181	      color: var(--text);
182	      cursor: pointer;
183	      font: inherit;
184	      font-size: 0.75rem;
185	      font-weight: bold;
186	      line-height: 1;
187	      text-align: center;
188	      vertical-align: middle;
189	      touch-action: manipulation;
190	      transition: background-color 0.2s ease, color 0.2s ease;
191	    }
192	    .help-button:focus-visible {
193	      outline: 2px solid currentColor;
194	      outline-offset: 2px;
195	    }
196	    @media (hover: hover) {
197	      /* Not currentColor: it would resolve to the hover color and hide the "?" */
198	      .help-button:hover {
199	        background: var(--text);
200	        color: var(--bg);
201	      }
202	    }
203	    .keys {
204	      display: none;
205	    }
206	    .keys.visible {
207	      display: inline;
208	    }
209	    @media (hover: none) and (pointer: coarse) {
210	      .hint .keys {
211	        display: none !important;
212	      }
213	      .help-button {
214	        display: none;
215	      }
216	    }
217	    kbd {
218	      display: inline-block;
219	      padding: 0.125rem 0.375rem;
220	      background: var(--kbd-bg);
221	      border: 1px solid transparent;
222	      border-radius: 0.25rem;
223	      font-family: monospace;
224	      font-size: 0.75em;
225	      line-height: 1.2;
226	    }
227	  </style>
228	</head>
229	<body>
230	  <main>
231	    <h1 class="visually-hidden">Animated Circle</h1>
232	    <button type="button" class="circle no-transition" aria-label="Change circle color" aria-describedby="status hint">
233	      <svg viewBox="0 0 100 100" aria-hidden="true" focusable="false" xmlns="http://www.w3.org/2000/svg">
234	        <circle cx="50" cy="50" r="50" fill="currentColor"/>
235	      </svg>
236	    </button>
237	    <p class="status" id="status" role="status">Blue</p>
238	    <p class="hint"><span id="hint"><span class="verb">Click</span> to cycle • <span class="double-verb">Double-click</span> to reset<span class="keys" id="keys"> • <kbd>Shift</kbd>+click reverse • <kbd>↑↓←→</kbd> navigate • <kbd>Home</kbd>/<kbd>End</kbd> jump</span></span> <button type="button" class="help-button" aria-label="Keyboard shortcuts" aria-expanded="false" aria-controls="keys"><span aria-hidden="true">?</span></button></p>
239	    <noscript><p class="hint">JavaScript is required to change the color.</p></noscript>
240	  </main>
241	  <script>
242	    const config = {
243	      colors: ['blue', 'red', 'green', 'amber', 'violet', 'cyan'],
244	      storageKey: 'circle-color',
245	      hapticDuration: 50,
246	      keySteps: { ArrowRight: 1, ArrowDown: 1, ArrowLeft: -1, ArrowUp: -1 },
247	    };
248	
249	    const DOM = {
250	      button: document.querySelector('.circle'),
251	      status: document.querySelector('.status'),
252	      helpButton: document.querySelector('.help-button'),
253	      keyHint: document.querySelector('.keys'),
254	      verbSpan: document.querySelector('.hint .verb'),
255	      doubleVerbSpan: document.querySelector('.hint .double-verb'),
256	    };
257	
258	    const state = {
259	      index: 0,
260	      shiftHeld: false,
261	      hoverCapable: true,
262	      reducedMotion: matchMedia('(prefers-reduced-motion: reduce)'),
263	      hoverQuery: matchMedia('(hover: none)'),
264	    };
265	
266	    function loadColor() {
267	      try {
268	        return localStorage.getItem(config.storageKey);
269	      } catch {
270	        return null;
271	      }
272	    }
273	
274	    function saveColor(color) {
275	      try {
276	        localStorage.setItem(config.storageKey, color);
277	      } catch {}
278	    }
279	
280	    function applyColor() {
281	      const color = config.colors[state.index];
282	      DOM.button.dataset.color = color === 'blue' ? '' : color;
283	      DOM.status.textContent = color[0].toUpperCase() + color.slice(1);
284	    }
285	
286	    function syncFromStorage(color = loadColor()) {
287	      const index = config.colors.indexOf(color);
288	      state.index = index === -1 ? 0 : index;
289	      applyColor();
290	    }
291	
292	    function setIndex(next, { haptic = false } = {}) {
293	      if (next === state.index) return;
294	      state.index = next;
295	      applyColor();
296	      saveColor(config.colors[state.index]);
297	
298	      if (haptic && navigator.vibrate) navigator.vibrate(config.hapticDuration);
299	
300	      if (state.reducedMotion.matches) return;
301	      DOM.button.classList.remove('color-changed');
302	      void DOM.button.offsetWidth;
303	      DOM.button.classList.add('color-changed');
304	    }
305	
306	    function changeColor(step) {
307	      setIndex((state.index + step + config.colors.length) % config.colors.length, { haptic: true });
308	    }
309	
310	    function updateDeviceVerbs() {
311	      state.hoverCapable = !state.hoverQuery.matches;
312	      DOM.verbSpan.textContent = state.hoverCapable ? 'Click' : 'Tap';
313	      DOM.doubleVerbSpan.textContent = state.hoverCapable ? 'Double-click' : 'Double-tap';
314	    }
315	
316	    function toggleKeyHintVisibility() {
317	      const expanded = DOM.keyHint.classList.toggle('visible');
318	      DOM.helpButton.setAttribute('aria-expanded', expanded);
319	    }
320	
321	    function syncKeyHint() {
322	      DOM.keyHint.classList.toggle('visible', state.hoverCapable);
323	      DOM.helpButton.setAttribute('aria-expanded', state.hoverCapable);
324	    }
325	
326	    function handleKeyDown(event) {
327	      if (event.key === 'Enter' || event.key === ' ') {
328	        if (!event.repeat) state.shiftHeld = event.shiftKey;
329	        if (event.key === 'Enter' && event.repeat) event.preventDefault();
330	        return;
331	      }
332	
333	      if (event.altKey || event.ctrlKey || event.metaKey) return;
334	
335	      if (event.key in config.keySteps) {
336	        event.preventDefault();
337	        changeColor(config.keySteps[event.key]);
338	      } else if (event.key === 'Home') {
339	        event.preventDefault();
340	        setIndex(0, { haptic: true });
341	      } else if (event.key === 'End') {
342	        event.preventDefault();
343	        setIndex(config.colors.length - 1, { haptic: true });
344	      }
345	    }
346	
347	    // Initialize
348	    syncFromStorage();
349	
350	    requestAnimationFrame(() => requestAnimationFrame(() => {
351	      DOM.button.classList.remove('no-transition');
352	    }));
353	
354	    updateDeviceVerbs();
355	    syncKeyHint();
356	    // e.g. a tablet gaining or losing a trackpad/keyboard
357	    state.hoverQuery.addEventListener('change', () => {
358	      updateDeviceVerbs();
359	      syncKeyHint();
360	    });
361	
362	    // Event listeners
363	    DOM.button.addEventListener('keydown', handleKeyDown);
364	    DOM.button.addEventListener('keyup', (event) => {
365	      if (event.key === ' ') state.shiftHeld = event.shiftKey;
366	    });
367	    DOM.button.addEventListener('blur', () => {
368	      state.shiftHeld = false;
369	    });
370	    DOM.button.addEventListener('click', (event) => {
371	      if (event.detail > 1) return;
372	      changeColor(event.shiftKey || state.shiftHeld ? -1 : 1);
373	      state.shiftHeld = false;
374	    });
375	    DOM.button.addEventListener('dblclick', (event) => {
376	      event.preventDefault();
377	      setIndex(0);
378	    });
379	    DOM.button.addEventListener('animationend', () => {
380	      DOM.button.classList.remove('color-changed');
381	    });
382	
383	    DOM.helpButton.addEventListener('click', toggleKeyHintVisibility);
384	
385	    addEventListener('storage', (event) => {
386	      if (event.key !== config.storageKey && event.key !== null) return;
387	      syncFromStorage(event.newValue);
388	    });
389	    // Storage events are not delivered while the page sits in the bfcache
390	    addEventListener('pageshow', (event) => {
391	      if (event.persisted) syncFromStorage();
392	    });
393	  </script>
394	</body>
395	</html>
