    // Event listeners
    function clearLongPressTimer() {
      if (state.longPressTimer) clearTimeout(state.longPressTimer);
      state.longPressTimer = null;
    }

    DOM.button.addEventListener('keydown', handleKeyDown);
    DOM.button.addEventListener('keyup', (event) => {
      if (event.key === ' ') state.shiftHeld = event.shiftKey;
    });
    DOM.button.addEventListener('blur', () => {
      state.shiftHeld = false;
      clearLongPressTimer();
    });
    DOM.button.addEventListener('pointerdown', (event) => {
      state.pointerDownTime = event.timeStamp;
      clearLongPressTimer();
      state.longPressTimer = setTimeout(() => {
        setIndex(0, { haptic: true });
      }, 500);
    });
    DOM.button.addEventListener('pointerup', clearLongPressTimer);
    DOM.button.addEventListener('pointercancel', clearLongPressTimer);
    DOM.button.addEventListener('click', (event) => {
      clearLongPressTimer();
      if (event.detail > 1) return;
      changeColor(event.shiftKey || state.shiftHeld ? -1 : 1);
      state.shiftHeld = false;
    });
    DOM.button.addEventListener('dblclick', (event) => {
      event.preventDefault();
      setIndex(0);
    });
    DOM.button.addEventListener('animationend', () => {
      DOM.button.classList.remove('color-changed');
    });

    DOM.helpButton.addEventListener('click', toggleKeyHintVisibility);

    addEventListener('storage', (event) => {
      if (event.key !== config.storageKey && event.key !== null) return;
      syncFromStorage(event.newValue);
    });
    // Storage events are not delivered while the page sits in the bfcache
    addEventListener('pageshow', (event) => {
      if (event.persisted) syncFromStorage();
    });
  </script>
